<?php require_once '../includes/config.php';requireAdmin();$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT c.*,u.name user_name,u.email user_email FROM complaints c JOIN users u ON u.id=c.user_id WHERE c.id=?');$s->bind_param('i',$id);$s->execute();$c=$s->get_result()->fetch_assoc();if(!$c){http_response_code(404);exit('Complaint not found.');}$days=max(0,3-(int)floor((time()-strtotime($c['date_submitted']))/86400));$title='Complaint #'.$c['id'];require '../includes/header.php';?><a class="btn btn-light" href="dashboard.php">← Back</a><div class="detail-grid" style="margin-top:18px"><section class="card"><div class="hero"><div><h1>Complaint #<?=$c['id']?></h1><p class="subtitle"><?=e($c['category'])?></p></div><span class="badge <?=$c['status']==='Resolved'?'badge-resolved':($c['status']==='In Progress'?'badge-progress':'badge-pending')?>"><?=e($c['status'])?></span></div><div class="detail-field"><div class="detail-label">Submitted by</div><p class="detail-text"><?=e($c['user_name'])?> · <?=e($c['user_email'])?></p></div><div class="detail-field"><div class="detail-label">Description</div><p class="detail-text"><?=e($c['description'])?></p></div><div class="detail-field"><div class="detail-label">Submitted</div><p class="detail-text"><?=date('d M Y, g:i A',strtotime($c['date_submitted']))?></p></div><?php if($c['date_resolved']):?><div class="detail-field"><div class="detail-label">Resolved</div><p class="detail-text"><?=date('d M Y, g:i A',strtotime($c['date_resolved']))?></p></div><?php endif;?></section><aside class="card"><h2>Escalation timeline</h2><div class="timeline"><div class="timeline-step done"><span class="timeline-dot"></span><strong>Submitted</strong><div class="subtitle">Complaint received</div></div><div class="timeline-step <?= $c['is_escalated']?'active':''?>"><span class="timeline-dot"></span><strong><?= $c['is_escalated']?'Escalated':'Auto-escalation'?></strong><div class="subtitle"><?= $c['is_escalated']?'Needs attention now':($c['status']==='Resolved'?'Not required':$days.' day(s) before escalation')?></div></div><div class="timeline-step <?= $c['status']==='Resolved'?'resolved':''?>"><span class="timeline-dot"></span><strong>Resolved</strong><div class="subtitle"><?= $c['date_resolved']?date('d M Y, g:i A',strtotime($c['date_resolved'])):'Not yet resolved'?></div></div></div></aside></div><?php require '../includes/footer.php';?>
